import {GAME_VARIATIONS,HIDDEN_VARIATIONS,configForGame} from '../../src/engine/types';
const course={name:'Independent',holes:Array.from({length:18},(_,i)=>({num:i+1,par:4,hcp:i+1,yards:100}))};
const cfg={rulesVersion:1,inputRulesVersion:1} as const;
const make=()=>['A','B','C','D'].map((name,i)=>({id:name,name,team:i<2?'R':'B',handicap:0,scores:Array(18).fill(i===0?3:5)}));
const holes=(f:any)=>Object.fromEntries(course.holes.map(h=>[h.num,typeof f==='function'?f(h.num):structuredClone(f)]));
let n=0;const eq=(name:string,actual:any,expected:any)=>{assert.deepEqual(actual,expected,name);console.log('PASS',name,JSON.stringify(actual));n++;};
for(const [name,config,expected] of [['tiered',{skinsTier:'tiered'},36],['progressive',{skinsTier:'progressive'},171],['birdie',{birdieMultiplier:true},36],['team',{teamSkins:true},9]] as any){
 const ps=make();const conf={...cfg,skinsMode:'gross',...config};const r=c.calcSkins(ps,course,true,'gross',conf);eq('skins '+name,r.totals.A,expected);eq('skins cash '+name,cash(ps,course,['skins_carry'],1,undefined,conf).netByPlayer.A,name==='team'?4.5:expected*.75);
}
{const ps=make();ps.forEach(p=>p.scores.fill(4));ps[0].scores[1]=3;ps[0].scores[2]=5;ps[2].scores[2]=3; // fail validation on hole3; hole4 tied and validates C
 const conf={...cfg,skinsMode:'gross' as const,validationRule:true};const r=c.calcSkins(ps,course,true,'gross',conf);eq('skins validation failed pot returned',r.totals.C,3);eq('skins validation cash',cash(ps,course,['skins_carry'],1,undefined,conf).netByPlayer.C,2.25);}
for(const [name,pressed,extra,expect] of [['weighted',true,{nassauWeights:[1,1,2]},8],['pressThePress',true,{pressThePress:true},19],['aloha',false,{alohaPressOn18:true},3.5]] as any){const ps=make().slice(0,2);const conf={...cfg,...extra};eq('Nassau '+name,calcNassauRules(ps,course,pressed,conf).totals.A,expect);eq('Nassau cash '+name,cash(ps,course,[pressed?'nassau_press':'nassau'],1,undefined,conf).netByPlayer.A,expect);}
{const ps=make().slice(0,2);ps.forEach(p=>p.scores.fill(4));ps[0].scores[6]=3;ps[0].scores[7]=3;
 eq('No press last off',calcNassauRules(ps,course,true,cfg).totals.A,2);const on={...cfg,noPressLast:true};eq('No press last children blocked',calcNassauRules(ps,course,true,on).bets.filter(b=>b.parent).length,1);eq('No press last cash',cash(ps,course,['nassau_press'],1,undefined,on).netByPlayer.A,2);
 // prior case only toggles child ledger on ties: give hole9 a B win for payout difference
 ps[1].scores[8]=3;eq('No press last changed cash',cash(ps,course,['nassau_press'],1,undefined,on).netByPlayer.A-cash(ps,course,['nassau_press'],1,undefined,cfg).netByPlayer.A,2);}
{const ps=make();ps.forEach(p=>p.scores.fill(4));ps[0].scores[0]=3;for(const [name,event,key,expected] of [['blind',{partnerId:null,isLoneWolf:true,blind:true,beforePlay:true},'blindWolf',9],['pig',{partnerId:'B',isLoneWolf:false,refused:true,beforePlay:true},'pigVariation',12]] as any){const aux={wolf:holes((h:number)=>({partnerId:ps[h%4].id,isLoneWolf:false}))};aux.wolf[1]=event;const conf={...cfg,[key]:true};eq('Wolf '+name,ledger('wolf',ps,course,aux,conf).totals.A,expected);eq('Wolf cash '+name,cash(ps,course,['wolf'],1,aux,conf).netByPlayer.A,expected);}
 ps[0].scores[0]=4;ps[1].scores[1]=3;const aux={wolf:holes({partnerId:null,isLoneWolf:true})},conf={...cfg,wolfCarryover:true};eq('Wolf carry',ledger('wolf',ps,course,aux,conf).totals.B,12);eq('Wolf carry cash',cash(ps,course,['wolf'],1,aux,conf).netByPlayer.B,12);
 const snake={snake:holes([])};snake.snake[1]=['A','B'];snake.snake[2]=['A'];eq('Snake progressive',cash(ps,course,['snake'],1,snake,{...cfg,progressiveSnake:true}).netByPlayer.A,-12);}
{const ps=make().slice(0,2);ps.forEach(p=>p.scores.fill(4));ps[0].scores[0]=3;const aux={junk:holes({sandies:[],barkies:[],greenie:null})};aux.junk[1]={sandies:['A'],barkies:['A'],greenie:null};eq('Junk cash stacked plus Nassau',cash(ps,course,['nassau'],1,aux,{...cfg,junkNassau:true}).netByPlayer.A,5);}
{const ps=make().slice(0,2);ps[0].scores.fill(4);ps[1].scores.fill(6);eq('Barracuda par',c.calcStableford(ps,course,{...cfg,modifiedStableford:true})[0].points,0);eq('Barracuda cash',cash(ps,course,['stableford'],1,undefined,{...cfg,modifiedStableford:true}).netByPlayer.A,1);
 ps.forEach(p=>p.scores.fill(4));ps[1].scores[0]=3;const aux={jokerDeclarations:{0:{A:[1,2],B:[1,2]}}};const conf={...cfg,jokerEnabled:true};eq('Joker points',c.calcStableford(ps,course,conf,aux)[0].points,42);eq('Joker cash',cash(ps,course,['stableford'],1,aux,conf).netByPlayer.B,1);
 ps[0].handicap=18;eq('Net points',c.calcStableford(ps,course,{...cfg,netHandicap:true})[0].points,54);eq('Net cash',cash(ps,course,['stableford'],1,undefined,{...cfg,netHandicap:true}).netByPlayer.A,1);
 ps[0].handicap=0;ps[1].handicap=2;ps[1].scores[0]=5;const bisque={bisque:holes({beforePlay:true,strokes:{A:0,B:0}})};bisque.bisque[1].strokes.B=2;eq('Bisque replaces indexed',cash(ps,course,['match_play'],1,bisque,{...cfg,bisqueHandicap:true,netHandicap:true}).netByPlayer.B,1);}
for(const [key,expected] of [['escalatingSegments',42],['sixesPresses',30]] as const){const ps=make();ps.slice(1).forEach(p=>p.scores.fill(4));const conf={...cfg,[key]:true};eq('Sixes '+key,c.calcSixes(ps,course,conf).totals.A,expected);eq('Sixes cash '+key,cash(ps,course,['sixes'],1,undefined,conf).netByPlayer.A,expected);}
{const ps=make();eq('Rabbit double cash',cash(ps,course,['rabbit'],1,undefined,{...cfg,doubleRabbit:true}).netByPlayer.A,9);}
for(const [key,expected] of [['birdieFlip',522],['eagleDoubles',265],['birdieBlocksBirdie',494]] as const){const ps=make();ps[1].scores.fill(5);ps[2].scores.fill(4);ps[3].scores.fill(6);if(key==='eagleDoubles')ps[0].scores[0]=2;if(key==='birdieBlocksBirdie')ps[2].scores[0]=3;const conf={...cfg,...(key==='birdieBlocksBirdie'?{birdieFlip:true}:{}),[key]:true};const r=c.calcVegas(ps.slice(0,2),ps.slice(2),course,conf);eq('Vegas '+key,r.team1Won-r.team2Won,expected);eq('Vegas cash '+key,cash(ps,course,['vegas'],1,undefined,conf).netByPlayer.A,expected);}
{const ps=make();const aux={bbb:holes({bingo:null,bango:null,bongo:null})};aux.bbb[1]={bingo:'A',bango:null,bongo:null};eq('BBB birdie',cash(ps,course,['bingo_bango_bongo'],1,aux,{...cfg,bbbBirdieDouble:true}).netByPlayer.A,1.5);}
for(const v of HIDDEN_VARIATIONS)eq('hidden normalized '+v.id,configForGame({...cfg,[v.configKey]:v.configValue},v.appliesTo[0])[v.configKey],undefined);
console.log('Independent hand-computed assertions:',n);
{const ps=make();ps.forEach((p,i)=>p.scores.fill(3+i));const groups=[{name:'one',players:ps.slice(0,2)},{name:'two',players:ps.slice(2)}];eq('Group skins isolated',cash(ps,course,['skins'],1,undefined,{...cfg,skinsMode:'gross',skinsScope:'group'},groups).netByPlayer,{A:9,B:-9,C:9,D:-9});eq('Field skins',cash(ps,course,['skins'],1,undefined,{...cfg,skinsMode:'gross'},groups).netByPlayer,{A:13.5,B:-4.5,C:-4.5,D:-4.5});
 const pair=ps.slice(0,2);pair[0].scores.fill(4);pair[1].scores.fill(3);pair[0].handicap=18;eq('Gross radio',cash(pair,course,['skins'],1,undefined,{...cfg,skinsMode:'gross'}).netByPlayer.A,-9);eq('Net radio',cash(pair,course,['skins'],1,undefined,{...cfg,skinsMode:'net'}).netByPlayer.A,0);
 pair.forEach(p=>p.scores.fill(4));eq('Tied leaders push',cash(pair,course,['stableford'],.03,undefined,cfg).transactions,[]);pair[0].scores[1]=0;pair[1].scores[1]=3;eq('Gap blocks final cash',cash(pair,course,['stableford'],1,undefined,cfg).pending,true);
}
{const ps=make().slice(0,3);ps.forEach(p=>p.scores.fill(4));const aux={bbb:holes({bingo:null,bango:null,bongo:null})};aux.bbb[1]={bingo:'A',bango:null,bongo:null};for(const bet of [.01,.03,5]){const r=cash(ps,course,['bingo_bango_bongo'],bet,aux,cfg);eq('Cents zero sum '+bet,Math.round(Object.values(r.netByPlayer).reduce((a,b)=>a+b,0)*100),0);assert.deepEqual(cash(ps,course,['bingo_bango_bongo'],bet,JSON.parse(JSON.stringify(aux)),cfg),r);r.transactions.forEach(t=>assert.ok(Math.abs(t.amount*100-Math.round(t.amount*100))<1e-8));}}
console.log('FINAL independent assertions:',n);
for(const game of ['alternate_shot','chapman'] as const){const ps=['A','B','C','D','E','F'].map((name,i)=>({id:name,name,handicap:36,team:['R','B','G'][Math.floor(i/2)],scores:Array(18).fill(0)}));const aux={teamCards:holes({R:4,B:5,G:3})};eq('Canonical '+game,cash(ps,course,[game],.05,aux,cfg).netByPlayer,{A:-.05,B:-.05,C:-.05,D:-.05,E:.1,F:.1});}
